import { Field, FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";

export function SwitchSizes() {
  return (
    <FieldGroup className="w-full max-w-[10rem]">
      <Field orientation="horizontal">
        <Switch size="sm" />
        <FieldLabel>Small</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Switch size="default" />
        <FieldLabel>Default</FieldLabel>
      </Field>
    </FieldGroup>
  );
}
